import React, { useState } from 'react'
import NavBar from './NavBar'
import BasicInput from '../Components/BasicInput'
import CustomButton from '../Components/CustomButton';
import { CircularProgress, Dialog, DialogTitle, DialogContent, DialogActions, Button } from '@mui/material';

const Home = () => {
  const [formData, setFormData] = useState({
    name: '',
    phoneNumber: '',
    question: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [dialog, setDialog] = useState({
    open: false,
    type: 'success', // 'success' or 'error'
    message: ''
  });

  const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwo9or_1gJnVmFdAOb4VPdeQpI-RRsvXVAS69J5MMk8Rtf-F4ZQ9OFHDDHwJFAbFT-fpQ/exec';

  const handleInputChange = (fieldName, value) => {
    setFormData(prev => ({
      ...prev,
      [fieldName]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const payload = {
        name: formData.name.trim(),
        phoneNumber: formData.phoneNumber.trim(),
        question: formData.question.trim()
      };

      const response = await fetch(GOOGLE_SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors', 
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload)
      });

      // Show success dialog
      setDialog({
        open: true,
        type: 'success',
        message: 'Message sent successfully! We will get back to you soon.'
      });
      
      setFormData({ name: '', phoneNumber: '', question: '' });

    } catch (error) {
      // Show error dialog
      setDialog({
        open: true,
        type: 'error',
        message: 'Message may have been sent. If you have urgent queries, please contact us directly.'
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCloseDialog = () => {
    setDialog(prev => ({ ...prev, open: false }));
  };

  return (
    <div className='relative min-h-screen rounded-xl my-2 w-full overflow-hidden'>
      
      <div className='absolute inset-0 bg-homebg bg-cover bg-center bg-no-repeat z-0' />
      
      <div className='absolute inset-0 bg-gradient-to-b from-black/10 via-black/20 to-black/70 z-1' />
      
      {/* Loader Overlay */}
      {isSubmitting && (
        <div className="fixed inset-0 min-h-screen bg-black/70 flex items-center justify-center z-50">
          <div className="flex flex-col items-center gap-4">
            <CircularProgress 
              color="inherit" 
              size={60} 
              sx={{ color: '#ffffff' }}
            />
            <p className="text-white text-lg font-medium">Sending your message...</p>
          </div>
        </div>
      )}
      
      <div className='relative z-10 flex flex-col justify-between p-5 min-h-screen'>
        <NavBar/>
        
        <div className='flex gap-3 items-center max-[750px]:flex-col flex-1'>
          <div className='flex-1 text-white max-[750px]:text-center'>
            <p className='text-H font-riope'>BT's TT Academy</p>
            <p className='font-in'>Freelance Table Tennis Coach | Table Tennis for everyone.</p>
          </div>

          <form onSubmit={handleSubmit} className='font-in flex-1 rounded-2xl max-[750px]:max-w-[400px] bg-black/35 backdrop-blur-md p-3'>
            <p className='text-stone-200 text-sm bg-gradient-to-r from-orange-500 via-orange-500 to-orange-600 py-1 px-2 rounded-xl shadow-md'>
              You can use this chat facility to clear any of your queries prior to Bookings ....
            </p>
            
            <BasicInput
              labelName="Name"
              fieldName="Name"
              placeholder="Enter your Name"
              width="100%"
              value={formData.name}
              onChange={(value) => handleInputChange('name', value)}
              required
            />
            
            <BasicInput
              labelName="Phone Number"
              fieldName="Phone Number"
              type="number"
              placeholder="Enter your phone number"
              width="100%"
              value={formData.phoneNumber}
              onChange={(value) => handleInputChange('phoneNumber', value)}
              required
            />

            <BasicInput
              labelName="Your Question"
              fieldName="Questions"
              type="multiline"
              placeholder="Try asking a detailed question"
              value={formData.question}
              onChange={(value) => handleInputChange('question', value)}
              required
            />
            
            <div className="mt-5 flex justify-end">
              <CustomButton 
                type="submit"
                message 
                size='small' 
                text={isSubmitting ? "Sending..." : "Send Message"}
                disabled={isSubmitting}
              />
            </div>
            
            <div className="mt-2 text-xs text-stone-400 text-center">
              Alternatively, you can WhatsApp us at +91 XXXXX XXXXX
            </div>
          </form>
        </div>
      </div>

      {/* Material-UI Dialog for messages */}
      <Dialog
        open={dialog.open}
        onClose={handleCloseDialog}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
        sx={{
          '& .MuiDialog-paper': {
            borderRadius: '12px',
            padding: '8px',
            minWidth: '300px'
          }
        }}
      >
        <DialogTitle 
          id="alert-dialog-title"
          sx={{ 
            color: dialog.type === 'success' ? '#4caf50' : '#f44336',
            fontWeight: 'bold',
            textAlign: 'center',
            padding: '16px 16px 8px 16px'
          }}
        >
          {dialog.type === 'success' ? 'Success!' : 'Notice'}
        </DialogTitle>
        <DialogContent sx={{ padding: '8px 16px' }}>
          <p id="alert-dialog-description" style={{ textAlign: 'center', margin: 0, lineHeight: '1.5' }}>
            {dialog.message}
          </p>
        </DialogContent>
        <DialogActions sx={{ justifyContent: 'center', padding: '16px 24px 16px 24px' }}>
          <Button 
            onClick={handleCloseDialog}
            variant="contained"
            sx={{
              backgroundColor: dialog.type === 'success' ? '#4caf50' : '#f44336',
              '&:hover': {
                backgroundColor: dialog.type === 'success' ? '#45a049' : '#da190b'
              },
              minWidth: '80px'
            }}
            autoFocus
          >
            OK
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  )
}

export default Home;
